    'dashboard_analytics_business_health_help' => '<strong>کاروباری صحت</strong><br>کاروباری صحت = آج کی فروخت کی کارکردگی کا مقابلہ گزشتہ 7 دنوں کے اوسط سے مائنَس واجب الادا بقایا انوائسز کے جرمانے کے ساتھ.<br><br><strong>موجودہ منطق:</strong><br>- فروخت کے موازنہ سے شروع ہوتی ہے.<br>- اگر آج کی فروخت 7 دن کے روزانہ اوسط کے برابر ہو تو اسکور تقریباً 50 ہے.<br>- اگر آج کی فروخت اوسط سے زیادہ ہو تو اسکور 100 تک بڑھتا ہے.<br>- اگر پچھلے 7 دنوں میں کوئی فروخت نہیں ہوئی لیکن آج فروخت ہوئی ہے، تو اسکور 75 ہو جاتا ہے.<br>- پھر 30 دن سے زیادہ پرانے واجب الادا بقایا فروخت اسکور کو کم کرتے ہیں.<br>- ہر واجب الادا انوائس 2 پوائنٹس کم کرتا ہے، زیادہ سے زیادہ جرمانہ 25 ہے.<br><br><strong>لیبلز:</strong><br>75-100 = بہترین<br>50-74 = اچھا<br>25-49 = اوسط<br>0-24 = توجہ کی ضرورت',
